func consensus(clades map[int]bool, list []int, taxa []Record, outgroup int) Tree {
	t := newTree(len(taxa))
	root := t.Next
	t.Next++
	mask := 0
	for _, x := range list {
		if x != outgroup {
			mask |= 1 << x
		}
	}
	t.connect(root, outgroup, 0)
	var build func(int, int)
	build = func(node,
		current int) {
		var maximal []int
		for c := range clades {
			if c != current && c&current == c {
				contained := false
				for d := range clades {
					if d != c && d != current && d&current == d && c&d == c {
						contained = true
						break
					}
				}
				if !contained {
					maximal = append(maximal,
						c)
				}
			}
		}
		sort.Ints(maximal)
		covered := 0
		for _, c := range maximal {
			v := t.Next
			t.Next++
			t.connect(node,
				v, 0)
			covered |= c
			build(v, c)
		}
		for _, x := range list {
			if current>>x&1 != 0 && covered>>x&1 == 0 {
				t.connect(node,
					x, 0)
			}
		}
	}
	build(root, mask)
	return t
